FROM (VALUES ($TAPIS$[{"id":"b7173ce9-bbb1-4979-b068-172e07f7a36e","hours":"Ouvert tous les jours, 10:00–20:30.","title":"Bazar Salama — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« Super magasin de tapis au cœur de la médina. Ismail et son équipe sont charmants et très compétents. La qualité des tapis est exceptionnellement bonne. J'ai hâte qu'ils arrivent ! », résume Sara Price."]},{"id":"2bd3de7c-ac19-48ad-a1b4-9c25dbbde694","hours":"Ouvert tous les jours, 10:00–19:00.","title":"Beldi Weave — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["Tapis marocains vintage faits main et décoration intérieure. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« J'ai pu trouver beaucoup de beaux tapis. Et un propriétaire très gentil !!! », résume 武田美紀."]},{"id":"80a2817c-e9f9-4f4b-a907-efb18901e39c","hours":"Ouvert tous les jours, 09:00–21:00.","title":"Chateau Des Souks — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["100% laine, fait main, expédition tous pays. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« J'ai visité le magasin avec ma mère en avril 2025. Notre guide nous a emmenés ici (au moins à la partie tapis de la boutique) et nous a dit que nous n'étions pas obligés d'acheter quoi que ce soit, ce qui était vrai.… », résume Robert Partyka."]},{"id":"78a55875-058a-40aa-b562-e9df6e7f9838","hours":"","title":"Dar Haram Cheekh — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["Tapis, poufs, coussins et sacs marocains faits main. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main."]},{"id":"793c144f-c1c5-47db-bd51-b86b8c089735","hours":"Ouvert tous les jours, 09:00–19:00.","title":"Dune Galerie — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["Spécialisé dans les tapis, les meubles, les bijoux et les céramiques anciennes. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« Ce magasin était incroyable ! Des articles de grande qualité et un service impeccable. Khalil et ses frères vous font sentir comme chez vous et vous expliquent chaque pièce qui vous intéresse. Nous le recommanderons… », résume Tom Yeatts."]},{"id":"7bbaf3cf-59fc-4b11-9f02-e4c9b0402f4a","hours":"","title":"El Ghali Art Gallery — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« J'ai visité cette magnifique boutique à Marrakech et j'ai été impressionné par la qualité et l'authenticité des tapis faits à la main. Le métier à tisser qu'ils utilisent pour les fabriquer est vraiment fascinant,… », résume Stelios Tzoumanis."]},{"id":"d978dd11-2ca5-4134-a519-e4bf5b880ce7","hours":"Ouvert tous les jours, 09:30–18:30.","title":"Imad Rugs - by Imad Farah — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« De beaux tapis de haute qualité, des pièces artisanales très uniques. Le service a été particulièrement agréable, pas de précipitation ni de pression, beaucoup de choix et une bonne ambiance dans le magasin. Nous… », résume Hana Mest."]},{"id":"cf96cbf3-1bda-44c3-90e2-bd193888a4a5","hours":"Ouvert tous les jours, 09:30–19:30.","title":"La Porte d''Or — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["La plus grande collection de tapis et kilims de luxe du Maroc. Un savoir-faire familial depuis 1970. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« Meilleure expérience d''achat de toute ma semaine au Maroc (Rabat et Marrakech). Je voulais un petit tapis et ils m''ont présenté tellement d''options en fonction de la couleur, de la taille et du type ! Les merveilleux… », résume Ava S."]},{"id":"58213f82-e29b-4f7c-84ae-82b26a006cbd","hours":"Ouvert tous les jours, 10:00–19:30.","title":"Lahandira — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« Notre beau tapis en laine est arrivé aujourd''hui à Berlin (juste 2 jours après notre retour de Marrakech), et nous ne pourrions être plus heureux ! Une belle pièce artisanale dont nous sommes tombés amoureux au moment… », résume Chris."]},{"id":"1621498d-403b-4ff2-baf3-db45d1e5f41e","hours":"Ouvert tous les jours, 09:00–19:00.","title":"Les Nomades de Marrakech — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["Showroom de tapis marocains artisanaux : techniques berbères ancestrales, pièces uniques au cœur de la Médina. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« J''ai eu une excellente expérience chez Les Nomades. Ils ont été très serviables et patients ! Ils ont expliqué les différents types de tapis et ont vraiment appris à connaître mon style afin de me recommander le… », résume Emily Schmitz."]},{"id":"fe449a73-9c44-4631-9350-f8b9242a829e","hours":"Ouvert tous les jours, 09:30–19:00.","title":"Nomads Crafts — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["Des créations uniques qui racontent une histoire, livraison internationale. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« Cette charmante boutique artisanale au cœur de la médina de Marrakech est un véritable trésor de l''artisanat marocain. Des tapis magnifiquement tissés à la main aux motifs complexes à la poterie exquise qui reflète le… », résume Omar Ch-hibat."]},{"id":"ecc940a8-e306-4d31-9947-c41a135f10ab","hours":"","title":"Palais Filali — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["Votre dose quotidienne de magnifiques tapis. Livraison internationale. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main."]},{"id":"9a0a86bf-37e6-4914-8ceb-10fd57627348","hours":"","title":"Secret de laine — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Route de l''Ourika","paragraphs":["Tapis berbères et décoration artisanale. À Marrakech, dans le quartier de Route de l''Ourika, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main."]},{"id":"d84dc07d-e9b6-402b-861c-b0a6b5ce83d8","hours":"Ouvert tous les jours, 10:00–19:00.","title":"Studio Sana Benzaitar — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Gueliz","paragraphs":["Spécialiste des Beni Mrirt marocains contemporains uniques et sur mesure. À Marrakech, dans le quartier de Gueliz, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main.","« Nous avons acheté 2 magnifiques tapis sur mesure, avons bénéficié d''un excellent service, le personnel très serviable et avons organisé un transport efficace des tapis jusqu''à notre domicile. Je recommande vivement le… », résume Turid Staveland Nygaard."]},{"id":"c17ebc87-c315-4dfa-bd93-53fe9462bd52","hours":"","title":"Woven Touch — pour un tapis berbère qui a une histoire","pretitle":"Marrakech — Medina","paragraphs":["Tapis marocains contemporains tissés main. À Marrakech, dans le quartier de Medina, l'adresse cultive un rapport singulier au tapis berbère — pièces vintage, kilims, boucherouite ou créations contemporaines tissées main."]}]$TAPIS$)) AS t(entries)
